<?php
// HTTP helpers and assertions for the Bookshop API checks. Lives outside the project.
const BASE = 'http://localhost:8089';
$GLOBALS['fails'] = 0;
$GLOBALS['passes'] = 0;

function req(string $method, string $path, array $headers = [], ?string $body = null): array
{
    $h = ['Accept: application/vnd.api+json'];
    foreach ($headers as $k => $v) {
        $h[] = "$k: $v";
    }
    $http = ['method' => $method, 'header' => implode("\r\n", $h), 'ignore_errors' => true, 'timeout' => 20];
    if (null !== $body) {
        $http['content'] = $body;
    }
    $raw = @file_get_contents(BASE.$path, false, stream_context_create(['http' => $http]));
    $status = 0;
    $ctype = '';
    $location = '';
    foreach ($http_response_header ?? [] as $line) {
        if (preg_match('#^HTTP/\S+\s+(\d{3})#', $line, $m)) {
            $status = (int) $m[1];
        }
        if (preg_match('#^Content-Type:\s*(.*)$#i', $line, $m)) {
            $ctype = trim($m[1]);
        }
        if (preg_match('#^Location:\s*(.*)$#i', $line, $m)) {
            $location = trim($m[1]);
        }
    }

    return ['status' => $status, 'ctype' => $ctype, 'location' => $location, 'body' => (string) $raw, 'json' => json_decode((string) $raw, true)];
}

function check(string $name, bool $ok, string $detail = ''): void
{
    if ($ok) {
        $GLOBALS['passes']++;
        echo "PASS  $name\n";
    } else {
        $GLOBALS['fails']++;
        echo "FAIL  $name  $detail\n";
    }
}

function expectStatus(string $name, array $r, int $status): void
{
    check("$name -> $status", $r['status'] === $status, "got {$r['status']}: ".substr($r['body'], 0, 400));
}

function expectError(string $name, array $r, int $status, ?string $parameter = null, ?string $pointer = null): void
{
    expectStatus($name, $r, $status);
    $errors = $r['json']['errors'] ?? null;
    check("$name is a JSON:API error document", is_array($errors) && $errors !== [] && str_contains($r['ctype'], 'application/vnd.api+json'), substr($r['body'], 0, 300));
    if (!is_array($errors)) {
        return;
    }
    $e = $errors[0];
    check("$name error has status string and title", ($e['status'] ?? null) === (string) $status && isset($e['title']) && isset($e['detail']), json_encode($e));
    if ($parameter !== null) {
        check("$name source.parameter=$parameter", ($e['source']['parameter'] ?? null) === $parameter, json_encode($e));
    }
    if ($pointer !== null) {
        check("$name source.pointer=$pointer", ($e['source']['pointer'] ?? null) === $pointer, json_encode($e));
    }
}

function ids(array $r): array
{
    return array_map(fn ($d) => $d['id'], $r['json']['data'] ?? []);
}
EOF
