<?php
require __DIR__.'/lib.php';

// Books list defaults and paging
$r = req('GET', '/books');
expectStatus('GET /books', $r, 200);
check('books default page has 10 items', count($r['json']['data']) === 10, count($r['json']['data'] ?? []));
check('books meta total is 14', ($r['json']['meta']['totalItems'] ?? null) === 14, json_encode($r['json']['meta'] ?? null));
check('books first link present', isset($r['json']['links']['first']) && isset($r['json']['links']['last']) && isset($r['json']['links']['next']), json_encode($r['json']['links'] ?? null));
check('books first page has no prev', !isset($r['json']['links']['prev']));
check('book has type/id/links.self/attributes', ($r['json']['data'][0]['type'] ?? '') === 'books' && ($r['json']['data'][0]['links']['self'] ?? '') === '/books/1' && isset($r['json']['data'][0]['attributes']['priceCents']) && isset($r['json']['data'][0]['attributes']['publishedAt']), json_encode($r['json']['data'][0] ?? null));
check('book has author relationship linkage', ($r['json']['data'][0]['relationships']['author']['data'] ?? null) === ['type' => 'authors', 'id' => '1'], json_encode($r['json']['data'][0]['relationships'] ?? null));
check('no included without include param', !isset($r['json']['included']), 'included present');

$p2 = req('GET', '/books?page%5Bnumber%5D=2');
check('page 2 has 4 items and no next', count($p2['json']['data'] ?? []) === 4 && !isset($p2['json']['links']['next']) && isset($p2['json']['links']['prev']), json_encode($p2['json']['links'] ?? null));
$past = req('GET', '/books?page%5Bnumber%5D=9');
expectStatus('page past last', $past, 200);
check('page past last is empty with no next', ($past['json']['data'] ?? null) === [] && !isset($past['json']['links']['next']), json_encode($past['json']));
$size = req('GET', '/books?page%5Bsize%5D=50');
check('page size 50 returns all 14', count($size['json']['data'] ?? []) === 14 && !isset($size['json']['links']['next']), '');
check('page size 50 has no next link', !isset($size['json']['links']['next']), json_encode($size['json']['links'] ?? null));
$one = req('GET', '/books?page%5Bsize%5D=1');
check('page size 1 returns one item, last=14', count($one['json']['data'] ?? []) === 1 && str_contains($one['json']['links']['last'] ?? '', 'page%5Bnumber%5D=14') || str_contains($one['json']['links']['last'] ?? '', 'page[number]=14'), json_encode($one['json']['links'] ?? null));
expectError('page size 0', req('GET', '/books?page%5Bsize%5D=0'), 400, 'page[size]');
expectError('page size 51', req('GET', '/books?page%5Bsize%5D=51'), 400, 'page[size]');
expectError('page size abc', req('GET', '/books?page%5Bsize%5D=abc'), 400, 'page[size]');
expectError('page number 0', req('GET', '/books?page%5Bnumber%5D=0'), 400, 'page[number]');

// Filters
$t = req('GET', '/books?filter%5Btitle%5D=DUNE');
check('title filter case-insensitive finds 5', ($t['json']['meta']['totalItems'] ?? null) === 5, json_encode($t['json']['meta'] ?? null));
$a = req('GET', '/books?filter%5Bauthor%5D=Frank%20Herbert');
check('author filter finds 5 Herbert books', ($a['json']['meta']['totalItems'] ?? null) === 5, json_encode($a['json']['meta'] ?? null));
$pr = req('GET', '/books?filter%5BminPrice%5D=1000&filter%5BmaxPrice%5D=1200');
check('price range 1000..1200 inclusive', ($pr['json']['meta']['totalItems'] ?? null) === 4, json_encode(['ids' => ids($pr), 'meta' => $pr['json']['meta'] ?? null]));
$pd = req('GET', '/books?filter%5BpublishedAfter%5D=2020-01-01&filter%5BpublishedBefore%5D=2020-12-31');
check('published range 2020 inclusive -> ids 10,11,12,13', ids($pd) === ['10', '11', '12', '13'], json_encode(ids($pd)));
$ins = req('GET', '/books?filter%5BinStock%5D=false');
check('inStock=false -> 2,6,12', ids($ins) === ['2', '6', '12'], json_encode(ids($ins)));
$inst = req('GET', '/books?filter%5BinStock%5D=true&page%5Bsize%5D=50');
check('inStock=true -> 11 books', ($inst['json']['meta']['totalItems'] ?? null) === 11, json_encode($inst['json']['meta'] ?? null));
$unknown = req('GET', '/books?filter%5Bfoo%5D=bar');
check('unknown filter ignored', ($unknown['json']['meta']['totalItems'] ?? null) === 14, '');
expectError('minPrice malformed', req('GET', '/books?filter%5BminPrice%5D=12.5'), 400, 'filter[minPrice]');
expectError('minPrice text', req('GET', '/books?filter%5BminPrice%5D=cheap'), 400, 'filter[minPrice]');
expectError('inStock malformed', req('GET', '/books?filter%5BinStock%5D=yes'), 400, 'filter[inStock]');
expectError('publishedAfter invalid date', req('GET', '/books?filter%5BpublishedAfter%5D=2020-02-30'), 400, 'filter[publishedAfter]');
expectError('publishedBefore bad format', req('GET', '/books?filter%5BpublishedBefore%5D=01/01/2020'), 400, 'filter[publishedBefore]');

// Sorting
$s = req('GET', '/books?sort=-priceCents,title&page%5Bsize%5D=50');
$prices = array_map(fn ($d) => [$d['attributes']['priceCents'], $d['attributes']['title']], $s['json']['data'] ?? []);
$sorted = $prices;
usort($sorted, fn ($x, $y) => [-$x[0], $x[1]] <=> [-$y[0], $y[1]]);
check('sort=-priceCents,title ordered', $prices === $sorted && $prices[0][0] === 3500, json_encode($prices));
$s2 = req('GET', '/books?sort=title&page%5Bsize%5D=50');
check('sort=title ascending first is A Wizard', ($s2['json']['data'][0]['attributes']['title'] ?? '') === 'A Wizard of Earthsea', json_encode($s2['json']['data'][0] ?? null));
$s3 = req('GET', '/books?sort=publishedAt&page%5Bsize%5D=50');
check('sort=publishedAt ascending first is 1965 Dune', ($s3['json']['data'][0]['id'] ?? '') === '4', json_encode(ids($s3)));
expectError('unknown sort field', req('GET', '/books?sort=stock'), 400, 'sort');

// Include
$inc = req('GET', '/books?include=author&page%5Bsize%5D=3');
check('include=author adds authors to included', count($inc['json']['included'] ?? []) >= 1 && ($inc['json']['included'][0]['type'] ?? '') === 'authors' && array_key_exists('name', $inc['json']['included'][0]['attributes'] ?? []), json_encode($inc['json']['included'] ?? null));
$anon = req('GET', '/books/10?include=author');
check('anonymous author name null in included', array_key_exists('name', $anon['json']['included'][0]['attributes'] ?? []) && ($anon['json']['included'][0]['attributes']['name'] ?? 'x') === null, json_encode($anon['json']['included'] ?? null));
expectError('unknown include path', req('GET', '/books?include=publisher'), 400, 'include');

// Single book
expectStatus('GET /books/4', req('GET', '/books/4'), 200);
expectStatus('unpublished book 3 is 404', req('GET', '/books/3'), 404);
expectStatus('book 999 is 404', req('GET', '/books/999'), 404);
expectStatus('malformed id /books/abc is 404', req('GET', '/books/abc'), 404);

// Authors
$au = req('GET', '/authors');
expectStatus('GET /authors', $au, 200);
check('authors: 5 in total', ($au['json']['meta']['totalItems'] ?? null) === 5, json_encode($au['json']['meta'] ?? null));
check('author 1 publishedBooks = 3', ($au['json']['data'][0]['attributes']['publishedBooks'] ?? null) === 3, json_encode($au['json']['data'][0] ?? null));
