// Partial update: only sent attributes change
$r = $patch('4', ['priceCents' => 2100]);
expectStatus('PATCH /books/4 price', $r, 200);
check('PATCH response is book document with new price', ($r['json']['data']['attributes']['priceCents'] ?? null) === 2100 && ($r['json']['data']['attributes']['title'] ?? null) === 'Dune' && ($r['json']['data']['attributes']['stock'] ?? null) === 10, json_encode($r['json']['data'] ?? null));
$b = $book(4)['attributes'] ?? [];
check('PATCH persisted and title/stock unchanged', ($b['priceCents'] ?? null) === 2100 && ($b['title'] ?? null) === 'Dune' && ($b['stock'] ?? null) === 10, json_encode($b));

$r = $patch('4', ['stock' => 9, 'title' => 'Dune (2nd ed.)', 'bogus' => 1, 'publishedAt' => '2000-01-01']);
