$b = $book(4)['attributes'] ?? [];
check('multiple attributes saved, publishedAt unchanged', ($b['stock'] ?? null) === 9 && ($b['title'] ?? null) === 'Dune (2nd ed.)' && ($b['publishedAt'] ?? null) === '1965-08-01', json_encode($b));

// Restore title right away (keep DB tidy)
$patch('4', ['title' => 'Dune', 'priceCents' => 2000, 'stock' => 10]);

