expectError('PATCH negative price 422', $patch('4', ['priceCents' => -1]), 422, null, '/data/attributes/priceCents');
expectError('PATCH negative stock 422', $patch('4', ['stock' => -3]), 422, null, '/data/attributes/stock');
expectError('PATCH non-integer price 422', $patch('4', ['priceCents' => 12.5]), 422, null, '/data/attributes/priceCents');
expectError('PATCH text price 422', $patch('4', ['priceCents' => 'cheap']), 422, null, '/data/attributes/priceCents');
expectError('PATCH string price 422', $patch('4', ['priceCents' => '1200']), 422, null, '/data/attributes/priceCents');
check('failed PATCH changed nothing', $book(4) === $before, json_encode($book(4)));

// Id mismatch, content type, not found, unpublished
expectError('PATCH data.id mismatch 409', $patch('4', ['stock' => 1], '5'), 409, null, '/data/id');
$r = req('PATCH', '/books/4', ['Content-Type' => 'application/json'], json_encode(['data' => ['type' => 'books', 'id' => '4', 'attributes' => ['stock' => 1]]]));
expectStatus('PATCH wrong content type 415', $r, 415);
expectStatus('PATCH unknown book 404', $patch('999', ['stock' => 1]), 404);
expectStatus('PATCH malformed id 404', $patch('abc', ['stock' => 1]), 404);
$r = $patch('3', ['priceCents' => 1900]);
expectStatus('PATCH unpublished book -> 204', $r, 204);
check('unpublished book updated', ($r['body'] === '') && (req('PATCH', '/books/3', $vnd, json_encode(['data' => ['type' => 'books', 'id' => '3', 'attributes' => ['priceCents' => 1800]]]))['status'] === 204), '');
$r = req('PATCH', '/books/3', $vnd, json_encode(['data' => ['type' => 'books', 'id' => '3', 'attributes' => ['priceCents' => 1800]]]));

// Purchases: validation and checks before payment
$pc = ['Customer-Id' => '3'];
$post = fn (array $lines, array $headers = $pc) => req('POST', '/purchases', ['Content-Type' => 'application/vnd.api+json'] + $headers, json_encode(['data' => ['type' => 'purchases', 'attributes' => ['lines' => $lines]]]));
expectError('POST without Customer-Id 401', req('POST', '/purchases', ['Content-Type' => 'application/vnd.api+json'], json_encode(['data' => ['type' => 'purchases', 'attributes' => ['lines' => []]]])), 401);
expectError('POST empty lines 422', $post([]), 422, null, '/data/attributes/lines');
expectError('POST string bookId 422', $post([['bookId' => '7', 'quantity' => 1]]), 422, null, '/data/attributes/lines/0/bookId');
expectError('POST quantity 0 422', $post([['bookId' => 7, 'quantity' => 0]]), 422, null, '/data/attributes/lines/0/quantity');
expectError('POST fractional quantity 422', $post([['bookId' => 7, 'quantity' => 1.5]]), 422);
expectError('POST unpublished book 422', $post([['bookId' => 3, 'quantity' => 1]]), 422, null, '/data/attributes/lines/0/bookId');
expectError('POST unknown book 422', $post([['bookId' => 999, 'quantity' => 1]]), 422, null, '/data/attributes/lines/0/bookId');
expectError('POST out of stock 409', $post([['bookId' => 2, 'quantity' => 1]]), 409);
expectError('POST total across lines 409', $post([['bookId' => 14, 'quantity' => 1], ['bookId' => 14, 'quantity' => 1]]), 409);
$r = req('POST', '/purchases', ['Content-Type' => 'application/json'] + $pc, json_encode(['data' => ['type' => 'purchases', 'attributes' => ['lines' => [['bookId' => 7, 'quantity' => 1]]]]]));
expectStatus('POST wrong content type 415', $r, 415);
check('no stock changed by failed purchases', ($book(14)['attributes']['stock'] ?? null) === 1 && ($book(2)['attributes']['stock'] ?? null) === 0, '');

