$r = $post([['bookId' => 7, 'quantity' => 2], ['bookId' => 14, 'quantity' => 1]]);
expectStatus('POST purchase 201', $r, 201);
check('Location header points at purchase', preg_match('#/purchases/\d+$#', $r['location']) === 1, $r['location']);
$d = $r['json']['data'] ?? [];
check('purchase total = 2*1200 + 1000', ($d['attributes']['totalCents'] ?? null) === 3400 && count($d['attributes']['lines'] ?? []) === 2, json_encode($d));
check('purchase line unit price current', ($d['attributes']['lines'][0] ?? null) === ['bookId' => 7, 'title' => 'Kindred', 'quantity' => 2, 'unitPriceCents' => 1200], json_encode($d['attributes']['lines'] ?? null));
check('stock decreased after purchase', ($book(7)['attributes']['stock'] ?? null) === 5 && ($book(14)['attributes']['stock'] ?? null) === 0, json_encode([$book(7), $book(14)]));
$myId = $d['id'] ?? '';
$g = req('GET', "/purchases/$myId", $pc);
expectStatus('GET new purchase as owner', $g, 200);
